Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net/rds: Restrict use of RDS/IB to the initial network
 namespace

Prevent using RDS/IB in network namespaces other than the initial one.
The existing RDS/IB code will not work properly in non-initial network
namespaces.

Fixes: d5a8ac28a7ff ("RDS-TCP: Make RDS-TCP work correctly when it is set up in a netns other than init_net")
Reported-by: syzbot+da8e060735ae02c8f3d1@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=da8e060735ae02c8f3d1
Signed-off-by: Greg Jumper <greg.jumper@oracle.com>
Signed-off-by: Allison Henderson <achender@kernel.org>
Link: https://patch.msgid.link/20260408080420.540032-3-achender@kernel.org
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The RDS/IB transport was not implemented with support for network namespaces, using global resources and not isolating per-namespace state. This leads to incorrect behavior or crashes when used in non-initial network namespaces.

Here is the patch:

-static int rds_set_transport(struct rds_sock *rs, sockptr_t optval, int optlen)
+static int rds_set_transport(struct net *net, struct rds_sock *rs,
+			     sockptr_t optval, int optlen)
 {
 	int t_type;

 	if (rs->rs_transport)
 		return -EOPNOTSUPP; /* previously attached to transport */

 	if (optlen != sizeof(int))
 		return -EINVAL;

 	if (copy_from_sockptr(&t_type, optval, sizeof(t_type)))
 		return -EFAULT;

 	if (t_type < 0 || t_type >= RDS_TRANS_COUNT)
 		return -EINVAL;

+	/* RDS/IB is restricted to the initial network namespace */
+	if (t_type != RDS_TRANS_TCP && !net_eq(net, &init_net))
+		return -EPROTOTYPE;
+
 	rs->rs_transport = rds_trans_get(t_type);

 	return rs->rs_transport ? 0 : -ENOPROTOOPT;
 }


 static int rds_setsockopt(struct socket *sock, int level, int optname,
 			  sockptr_t optval, unsigned int optlen)
 {
 	struct rds_sock *rs = rds_sk_to_rs(sock->sk);
+	struct net *net = sock_net(sock->sk);
 	int ret;

 	if (level != SOL_RDS) {
 		ret = -ENOPROTOOPT;
 		goto out;
 	}

 	switch (optname) {
 	case RDS_CANCEL_SENT_TO:
 		ret = rds_cancel_sent_to(rs, optval, optlen);
 		break;
 	case RDS_GET_MR:
 		ret = rds_get_mr(rs, optval, optlen);
 		break;
 	case RDS_GET_MR_FOR_DEST:
 		ret = rds_get_mr_for_dest(rs, optval, optlen);
 		break;
 	case RDS_FREE_MR:
 		ret = rds_free_mr(rs, optval, optlen);
 		break;
 	case RDS_RECVERR:
 		ret = rds_set_bool_option(&rs->rs_recverr, optval, optlen);
 		break;
 	case RDS_CONG_MONITOR:
 		ret = rds_cong_monitor(rs, optval, optlen);
 		break;
 	case SO_RDS_TRANSPORT:
 		lock_sock(sock->sk);
-		ret = rds_set_transport(rs, optval, optlen);
+		ret = rds_set_transport(net, rs, optval, optlen);
 		release_sock(sock->sk);
 		break;
 	case SO_TIMESTAMP_OLD:
 	case SO_TIMESTAMP_NEW:
 		lock_sock(sock->sk);
 		ret = rds_enable_recvtstamp(sock->sk, optval, optlen, optname);
 		release_sock(sock->sk);
 		break;
 	case SO_RDS_MSG_RXPATH_LATENCY:
 		ret = rds_recv_track_latency(rs, optval, optlen);
 		break;
 	default:
 		ret = -ENOPROTOOPT;
 	}
 out:
 	return ret;
 }



